def _build_o6_9_inputs(o6_9: dict, ama_additional: dict) -> dict:
    """o6_9 declared quantities (Informationsblatt Juni 2026, 3.1/3.2).

    A canonical `oepul.measures.o6_9` value wins; otherwise the AMA
    MFA-Angaben totals from the canonical builder are used. An existing
    MFA-Angaben row is passed on as `mfa_declaration_present`, so OPA can
    tell "declared nothing" apart from "no declaration data at all".
    """
    canonical_volumes = o6_9.get("declared_volumes_m3") or {}
    livestock = ama_additional.get("livestock") or {}
    mfa_angaben = livestock.get("mfa_angaben") or {}
    by_method = mfa_angaben.get("ausgebrachte_m3_nach_verfahren") or {}

    def pick(key: str, fallback):
        value = canonical_volumes.get(key)
        return value if value is not None else fallback

    volumes = {key: pick(key, by_method.get(mfa_key)) for key, mfa_key in _O6_9_MFA_VOLUME_FIELDS}
    volumes["separated_cattle_slurry"] = pick(
        "separated_cattle_slurry", mfa_angaben.get("separierte_m3_rinderguelle")
    )
    declaration_present = o6_9.get("mfa_declaration_present")
    if declaration_present is None:
        declaration_present = mfa_angaben.get("mfa_angaben_vorhanden")
    return {
        "declared_volumes_m3": volumes,
        "mfa_declaration_present": declaration_present,
    }

